package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.service.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final CheckoutService checkout;private final AuthService auth;private final OrderRepository orders;private final in.foodcart.service.payments.PaymentService payments;private final VendorRepository vendors;public OrderController(CheckoutService c,AuthService a,OrderRepository o,in.foodcart.service.payments.PaymentService p,VendorRepository v){checkout=c;auth=a;orders=o;payments=p;vendors=v;}/** Online: creates the order unpaid and starts the payment; the order reaches the vendor once the payment is confirmed. Pay at the stall: the order is placed now and payment is null. */ @PostMapping public java.util.Map<String,Object> create(@RequestHeader("Authorization") String header,@RequestBody CheckoutService.Request request){OrderEntity o=checkout.create(auth.actor(header,"CUSTOMER"),request);java.util.Map<String,Object> out=new java.util.LinkedHashMap<>();out.put("order",o);out.put("payment",o.cash()?null:payments.start(o));return out;}/**
   * The customer's orders still in progress (new, accepted, preparing, ready), latest first, for the live-orders bar at
   * the bottom of the storefront. Orders older than two days that nobody closed are not shown.
   */
  @GetMapping("/active") public java.util.List<java.util.Map<String,Object>> active(@RequestHeader("Authorization") String header){String customer=auth.actor(header,"CUSTOMER");java.util.List<java.util.Map<String,Object>> rows=new java.util.ArrayList<>();for(OrderEntity o:orders.findByCustomerIdAndStatusInAndCreatedAtAfterOrderByCreatedAtDesc(customer,java.util.List.of(in.foodcart.domain.OrderStatus.PLACED,in.foodcart.domain.OrderStatus.ACCEPTED,in.foodcart.domain.OrderStatus.PREPARING,in.foodcart.domain.OrderStatus.READY),java.time.Instant.now().minus(java.time.Duration.ofDays(2)))){java.util.Map<String,Object> row=new java.util.LinkedHashMap<>();row.put("id",o.id);row.put("orderNumber",o.orderNumber);row.put("status",o.status);row.put("itemCount",o.items.stream().mapToInt(i->i.quantity).sum());row.put("scheduledFor",o.scheduledFor);row.put("type",o.type);vendors.findById(o.vendorId).ifPresent(v->{row.put("vendorName",v.name);row.put("vendorSlug",v.slug);});rows.add(row);}return rows;}
  /** The customer's own order, for the status page. The stall's phone is shared only once the order is paid, or placed to pay at the stall (the customer calls to cancel). */
  @GetMapping("/{id}") public java.util.Map<String,Object> get(@RequestHeader("Authorization") String header,@PathVariable String id){String customer=auth.actor(header,"CUSTOMER");OrderEntity o=orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found"));if(!o.customerId.equals(customer))throw new SecurityException("Order not found");
    java.util.Map<String,Object> vendor=new java.util.LinkedHashMap<>();vendors.findById(o.vendorId).ifPresent(v->{vendor.put("name",v.name);vendor.put("slug",v.slug);vendor.put("address",v.address);if(v.location!=null&&v.location.lat!=null){vendor.put("lat",v.location.lat);vendor.put("lng",v.location.lng);}boolean paid=o.status!=in.foodcart.domain.OrderStatus.PAYMENT_PENDING&&o.status!=in.foodcart.domain.OrderStatus.EXPIRED;if(paid)vendor.put("phone",v.mobile);});
    java.util.Map<String,Object> result=new java.util.LinkedHashMap<>();result.put("order",o);result.put("vendor",vendor);return result;}}
